<?php
declare(strict_types=1);

function nzasec_account_blocked(array $db,string $uid): bool {return nzc_user_blocked($db,$uid);}
function nzasec_risk(array $db,string $uid): array {
    $score=0;$reasons=[];$rejected=0;$flaggedPosts=0;$reports=0;$dup=0;$messages=0;
    foreach($db['posts']??[]as$p)if(($p['user_id']??'')===$uid){if(($p['status']??'')==='rejected')$rejected++;if(!empty($p['moderation']['flagged']))$flaggedPosts++;}
    foreach($db['reports']??[]as$r){if(($r['reported_user_id']??'')===$uid)$reports++;if(($r['reporter_id']??'')==='system-duplicate'&&($r['details']??'')!==''&&($r['user_id']??'')===$uid)$dup++;if(($r['reported_user_id']??'')===$uid&&str_contains((string)($r['reason']??''),'پیام'))$messages++;}
    $score=min(100,$rejected*12+$flaggedPosts*18+$reports*16+$dup*30+$messages*20);if($rejected)$reasons[]=$rejected.' آگهی ردشده';if($flaggedPosts)$reasons[]=$flaggedPosts.' آگهی علامت‌گذاری‌شده';if($reports)$reasons[]=$reports.' گزارش علیه کاربر';if($dup)$reasons[]=$dup.' تلاش تکراری';if($messages)$reasons[]=$messages.' پیام پرریسک';return['score'=>$score,'reasons'=>$reasons];
}
function nzasec_admin_guard(): array {
    nzc_session_open();$db=nzc_db_read();$admin=nzc_require_admin($db);if(!nzc_csrf_valid())throw new RuntimeException('درخواست نامعتبر است.');
    if(function_exists('nzauth_is_elevated')&&!nzauth_is_elevated($admin)){nzc_flash('برای این عملیات ابتدا تأیید امنیتی مدیریت را انجام دهید.','warn');nzc_redirect('/nz?page=admin');}
    return[$db,$admin];
}
function nzasec_find_user(array $db,string $uid,array $admin): array {
    if($uid===''||$uid===($admin['id']??''))throw new RuntimeException('کاربر انتخاب‌شده معتبر نیست.');foreach($db['users']??[]as$u)if(($u['id']??'')===$uid)return$u;throw new RuntimeException('کاربر پیدا نشد.');
}
function nzasec_handle_post(string $action): never {
    [$db,$admin]=nzasec_admin_guard();
    if(in_array($action,['admin_block_user','admin_unblock_user','admin_send_notice'],true)){
        $uid=trim((string)($_POST['user_id']??''));$target=nzasec_find_user($db,$uid,$admin);$reason=mb_substr(trim((string)($_POST['reason']??'')),0,500);
        if($action==='admin_block_user'){
            nzc_db_write(function(&$db)use($uid,$admin,$reason){$updated=false;foreach($db['blocks']??[]as&$b)if(($b['user_id']??'')===$uid){$b['status']='active';$b['reason']=$reason!==''?$reason:'تصمیم مدیر امنیت';$b['updated_at']=nzc_now();$b['admin_id']=$admin['id'];$updated=true;break;}unset($b);if(!$updated)$db['blocks'][]=['id'=>nzc_uid('ban'),'user_id'=>$uid,'status'=>'active','reason'=>$reason!==''?$reason:'تصمیم مدیر امنیت','admin_id'=>$admin['id'],'created_at'=>nzc_now()];nzc_support_message($db,$uid,'حساب شما موقتاً برای بررسی امنیتی محدود شده است. برای پیگیری با پشتیبانی گفتگو کنید.');nzc_notify($db,$uid,'حساب شما برای بررسی امنیتی محدود شده است.','high');});nzc_audit($admin,'admin_block_user','user',$uid,['reason'=>$reason]);nzc_flash('حساب کاربر محدود شد.');nzc_redirect('/nz?page=admin&tab=users');
        }
        if($action==='admin_unblock_user'){
            nzc_db_write(function(&$db)use($uid,$admin){foreach($db['blocks']??[]as&$b)if(($b['user_id']??'')===$uid){$b['status']='inactive';$b['updated_at']=nzc_now();$b['unblocked_by']=$admin['id'];}unset($b);nzc_support_message($db,$uid,'محدودیت امنیتی حساب شما برداشته شد.');nzc_notify($db,$uid,'محدودیت حساب برداشته شد.');});nzc_audit($admin,'admin_unblock_user','user',$uid);nzc_flash('محدودیت حساب برداشته شد.');nzc_redirect('/nz?page=admin&tab=users');
        }
        $text=mb_substr(trim((string)($_POST['message']??'')),0,1200);if($text==='')throw new RuntimeException('متن پیام خالی است.');nzc_db_write(function(&$db)use($uid,$text){nzc_support_message($db,$uid,$text);nzc_notify($db,$uid,$text);});nzc_audit($admin,'admin_send_notice','user',$uid,['length'=>mb_strlen($text)]);nzc_flash('پیام برای کاربر ارسال شد.');nzc_redirect('/nz?page=admin&tab=users');
    }
    if(in_array($action,['admin_set_post_status','admin_toggle_featured'],true)){
        $pid=trim((string)($_POST['post_id']??''));if($pid==='')throw new RuntimeException('آگهی مشخص نیست.');$status=trim((string)($_POST['status']??''));$allowed=['published','pending','rejected','archived','deleted'];if($action==='admin_set_post_status'&&!in_array($status,$allowed,true))throw new RuntimeException('وضعیت آگهی معتبر نیست.');
        nzc_db_write(function(&$db)use($pid,$status,$action,$admin){$found=false;foreach($db['posts']as&$p){if(($p['id']??'')!==$pid)continue;$found=true;if($action==='admin_toggle_featured'){$p['featured']=empty($p['featured']);$msg=!empty($p['featured'])?'آگهی شما ویژه شد.':'وضعیت ویژه آگهی برداشته شد.';}else{$p['status']=$status;$p['review_status']=$status==='published'?'approved':($status==='rejected'?'rejected':($p['review_status']??''));$p['reviewed_at']=nzc_now();$p['reviewed_by']=$admin['id'];if($status==='published'&&empty($p['published_at']))$p['published_at']=nzc_now();$labels=['published'=>'منتشر','pending'=>'در انتظار بررسی','rejected'=>'رد','archived'=>'بایگانی','deleted'=>'حذف'];$msg='وضعیت آگهی «'.($p['title']??'آگهی').'» به «'.($labels[$status]??$status).'» تغییر کرد.';}$p['updated_at']=nzc_now();$owner=(string)($p['user_id']??'');if($owner!=='')nzc_notify($db,$owner,$msg);break;}unset($p);if(!$found)throw new RuntimeException('آگهی پیدا نشد.');});nzc_audit($admin,$action,'post',$pid,['status'=>$status]);nzc_flash($action==='admin_toggle_featured'?'وضعیت ویژه آگهی تغییر کرد.':'وضعیت آگهی تغییر کرد.');nzc_redirect('/nz?page=admin&tab=posts');
    }
    if(in_array($action,['admin_resolve_report','admin_reopen_report'],true)){
        $rid=trim((string)($_POST['report_id']??''));$resolved=$action==='admin_resolve_report';nzc_db_write(function(&$db)use($rid,$resolved,$admin){$found=false;foreach($db['reports']as&$r)if(($r['id']??'')===$rid){$r['status']=$resolved?'resolved':'open';$r[$resolved?'resolved_at':'reopened_at']=nzc_now();$r[$resolved?'resolved_by':'reopened_by']=$admin['id'];$found=true;break;}unset($r);if(!$found)throw new RuntimeException('گزارش پیدا نشد.');});nzc_audit($admin,$action,'report',$rid);nzc_flash($resolved?'گزارش بسته شد.':'گزارش دوباره باز شد.');nzc_redirect('/nz?page=admin&tab=reports');
    }
    throw new RuntimeException('عملیات مدیریتی معتبر نیست.');
}
function nzasec_recent_audit(int $limit=80): array {
    $pdo=nzstore_sqlite();if(!$pdo)return[];try{$st=$pdo->prepare('SELECT actor_id,action,target_type,target_id,ip,payload,created_at FROM nz_audit ORDER BY id DESC LIMIT ?');$st->bindValue(1,max(1,min(200,$limit)),PDO::PARAM_INT);$st->execute();return$st->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){return[];}
}
function nzasec_status_label(string $s): string {return['published'=>'منتشر','pending'=>'در انتظار','rejected'=>'ردشده','archived'=>'بایگانی','deleted'=>'حذف‌شده','sold'=>'فروخته‌شده'][$s]??$s;}
function nzasec_admin_html(array $db): string {
    $csrf=nzc_e($_SESSION['csrf']??'');$q=mb_strtolower(trim((string)($_GET['admin_q']??'')),'UTF-8');$tab=(string)($_GET['tab']??'overview');
    $users=$db['users']??[];$posts=$db['posts']??[];$reports=$db['reports']??[];$convs=$db['conversations']??[];
    $published=count(array_filter($posts,fn($p)=>($p['status']??'')==='published'));$pending=count(array_filter($posts,fn($p)=>($p['status']??'')==='pending'));$openReports=count(array_filter($reports,fn($r)=>($r['status']??'open')==='open'));$blocked=count(array_filter($users,fn($u)=>nzasec_account_blocked($db,(string)($u['id']??''))));$support=count(array_filter($convs,fn($c)=>(($c['type']??'')==='support'||($c['post_id']??'')===NZC_SUPPORT_POST)));$views=array_sum(array_map(fn($p)=>(int)($p['views']??0),$posts));
    $h='<section class="nzadmin-shell"><div class="nzadmin-hero"><div><h2>داشبورد کامل مدیریت</h2><p>کنترل کاربران، آگهی‌ها، گزارش‌ها، پشتیبانی، امنیت و وضعیت سرویس</p></div><div class="nzadmin-tools"><a class="btn ghost" href="/nz-health.php" target="_blank">Health</a><a class="btn ghost" href="/nz-sms-status.php" target="_blank">SMS</a><a class="btn ghost" href="/nz-backup-export.php">خروجی پشتیبان</a></div></div><div class="nzadmin-kpis"><div><b>'.count($users).'</b><span>کاربر</span></div><div><b>'.$blocked.'</b><span>محدود</span></div><div><b>'.$published.'</b><span>آگهی منتشر</span></div><div><b>'.$pending.'</b><span>در انتظار</span></div><div><b>'.$openReports.'</b><span>گزارش باز</span></div><div><b>'.number_format($views).'</b><span>بازدید</span></div></div>';
    $tabs=['overview'=>'نمای کلی','users'=>'کاربران','posts'=>'آگهی‌ها','reports'=>'گزارش‌ها','audit'=>'رویدادها'];$h.='<nav class="nzadmin-tabs">';foreach($tabs as$k=>$v)$h.='<a class="'.($tab===$k?'active':'').'" href="/nz?page=admin&tab='.$k.'">'.$v.'</a>';$h.='</nav><form class="nzadmin-search" method="get"><input type="hidden" name="page" value="admin"><input type="hidden" name="tab" value="'.nzc_e($tab).'"><input name="admin_q" value="'.nzc_e((string)($_GET['admin_q']??'')).'" placeholder="جستجو در نام، شماره، عنوان آگهی یا گزارش"><button class="btn ghost">جستجو</button></form>';
    if($tab==='overview'){
        $otp=function_exists('nzotp_ready')&&nzotp_ready();$h.='<div class="nzadmin-grid"><section class="surface"><h3>وضعیت عملیاتی</h3><div class="nzadmin-health"><span>ذخیره‌سازی</span><b>'.nzc_e(nzstore_backend()).'</b></div><div class="nzadmin-health"><span>OTP/SMS</span><b>'.($otp?'آماده':'نیازمند تنظیم').'</b></div><div class="nzadmin-health"><span>گفتگوی پشتیبانی</span><b>'.$support.'</b></div><div class="nzadmin-health"><span>گزارش باز</span><b>'.$openReports.'</b></div></section><section class="surface"><h3>اقدام‌های سریع</h3><a class="nzadmin-link" href="/nz?page=admin&tab=posts&admin_q=pending">بررسی آگهی‌ها</a><a class="nzadmin-link" href="/nz?page=admin&tab=reports">رسیدگی به گزارش‌ها</a><a class="nzadmin-link" href="/nz?page=admin&tab=users">مدیریت کاربران</a><a class="nzadmin-link" href="/nz?page=admin#risk-users">کاربران پرریسک</a></section></div>';
    }
    if($tab==='users'){
        $rows=[];foreach($users as$u){$hay=mb_strtolower(implode(' ',[(string)($u['name']??''),(string)($u['phone']??''),(string)($u['id']??'')]),'UTF-8');if($q!==''&&!str_contains($hay,$q))continue;$rows[]=$u;}usort($rows,fn($a,$b)=>strcmp((string)($b['created_at']??''),(string)($a['created_at']??'')));$h.='<section class="surface"><h3>کاربران ('.count($rows).')</h3>';if(!$rows)$h.='<div class="empty">کاربری پیدا نشد.</div>';foreach(array_slice($rows,0,100)as$u){$uid=(string)($u['id']??'');$isAdmin=nzc_is_admin($u);$isBlocked=nzasec_account_blocked($db,$uid);$risk=nzasec_risk($db,$uid);$userPosts=count(array_filter($posts,fn($p)=>($p['user_id']??'')===$uid));$h.='<article class="nzadmin-row"><div class="nzadmin-grow"><b>'.nzc_e($u['name']??'کاربر').' '.($isAdmin?'<em>مدیر</em>':'').'</b><small dir="ltr">'.nzc_e($u['phone']??'بدون شماره').'</small><small>'.$userPosts.' آگهی · ریسک '.$risk['score'].'/100 · '.($isBlocked?'محدود':'فعال').'</small></div>';if(!$isAdmin){$h.='<form method="post"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="'.($isBlocked?'admin_unblock_user':'admin_block_user').'"><input type="hidden" name="user_id" value="'.nzc_e($uid).'">'.(!$isBlocked?'<input name="reason" maxlength="500" placeholder="دلیل محدودیت">':'').'<button class="btn '.($isBlocked?'primary':'danger').'">'.($isBlocked?'رفع محدودیت':'محدودسازی').'</button></form><form method="post"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="admin_send_notice"><input type="hidden" name="user_id" value="'.nzc_e($uid).'"><input name="message" maxlength="1200" required placeholder="پیام مستقیم"><button class="btn ghost">ارسال</button></form>';}$h.='</article>';}$h.='</section>';
    }
    if($tab==='posts'){
        $rows=[];foreach($posts as$p){$hay=mb_strtolower(implode(' ',[(string)($p['title']??''),(string)($p['id']??''),(string)($p['status']??''),(string)($p['city']??'')]),'UTF-8');if($q!==''&&!str_contains($hay,$q)&&!($q==='pending'&&($p['status']??'')==='pending'))continue;$rows[]=$p;}usort($rows,fn($a,$b)=>strcmp((string)($b['created_at']??''),(string)($a['created_at']??'')));$h.='<section class="surface"><h3>همه آگهی‌ها ('.count($rows).')</h3>';if(!$rows)$h.='<div class="empty">آگهی پیدا نشد.</div>';foreach(array_slice($rows,0,120)as$p){$pid=(string)($p['id']??'');$h.='<article class="nzadmin-row"><div class="nzadmin-grow"><b>'.nzc_e($p['title']??'آگهی').(!empty($p['featured'])?' ⭐':'').'</b><small>'.nzc_e(nzasec_status_label((string)($p['status']??''))).' · '.nzc_e($p['city']??'').' · '.number_format((int)($p['views']??0)).' بازدید</small><a href="/nz?id='.rawurlencode($pid).'" target="_blank">مشاهده آگهی</a></div><form method="post" class="nzadmin-inline"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="admin_set_post_status"><input type="hidden" name="post_id" value="'.nzc_e($pid).'"><select name="status"><option value="published">منتشر</option><option value="pending">در انتظار</option><option value="rejected">ردشده</option><option value="archived">بایگانی</option><option value="deleted">حذف</option></select><button class="btn ghost">اعمال</button></form><form method="post"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="admin_toggle_featured"><input type="hidden" name="post_id" value="'.nzc_e($pid).'"><button class="btn '.(!empty($p['featured'])?'ghost':'primary').'">'.(!empty($p['featured'])?'لغو ویژه':'ویژه‌کردن').'</button></form></article>';}$h.='</section>';
    }
    if($tab==='reports'){
        $rows=$reports;usort($rows,fn($a,$b)=>strcmp((string)($b['created_at']??''),(string)($a['created_at']??'')));$h.='<section class="surface"><h3>گزارش‌ها ('.count($rows).')</h3>';if(!$rows)$h.='<div class="empty">گزارشی وجود ندارد.</div>';foreach(array_slice($rows,0,120)as$r){$hay=mb_strtolower(implode(' ',[(string)($r['reason']??''),(string)($r['details']??''),(string)($r['post_title']??''),(string)($r['id']??'')]),'UTF-8');if($q!==''&&!str_contains($hay,$q))continue;$open=($r['status']??'open')==='open';$rid=(string)($r['id']??'');$h.='<article class="nzadmin-row"><div class="nzadmin-grow"><b>'.nzc_e($r['reason']??'گزارش').' '.(($r['priority']??'')==='high'?'<em>فوری</em>':'').'</b><small>'.nzc_e($r['post_title']??'').' · '.nzc_e($r['details']??'').'</small><small>'.nzc_e($open?'باز':'بسته').' · '.nzc_e($r['created_at']??'').'</small></div><form method="post"><input type="hidden" name="csrf" value="'.$csrf.'"><input type="hidden" name="action" value="'.($open?'admin_resolve_report':'admin_reopen_report').'"><input type="hidden" name="report_id" value="'.nzc_e($rid).'"><button class="btn '.($open?'primary':'ghost').'">'.($open?'بستن گزارش':'بازکردن مجدد').'</button></form></article>';}$h.='</section>';
    }
    if($tab==='audit'){
        $audit=nzasec_recent_audit();$h.='<section class="surface"><h3>رویدادهای مدیریتی و امنیتی</h3>';if(!$audit)$h.='<div class="empty">هنوز رویدادی ثبت نشده است.</div>';foreach($audit as$a){$payload=json_decode((string)($a['payload']??''),true);$h.='<div class="nzasec-audit"><b>'.nzc_e($a['action']??'رویداد').'</b><span>'.nzc_e(($a['target_type']??'').' '.($a['target_id']??'')).' · '.nzc_e(date('Y/m/d H:i',strtotime($a['created_at']??'now'))).'</span>'.(!empty($payload)?'<small>'.nzc_e(mb_substr(json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?:'',0,300)).'</small>':'').'</div>';}$h.='</section>';
    }
    return$h.'</section>';
}
function nzasec_enhance(string $html): string {
    if(($_GET['page']??'')!=='admin')return$html;nzc_session_open();$db=nzc_db_read();$u=nzc_current_user($db);if(!$u||!nzc_is_admin($u))return$html;$extra=nzasec_admin_html($db);$html=str_replace('</main>',$extra.'</main>',$html);$css='<style id="nzasec-style">.nzadmin-shell{margin-top:16px}.nzadmin-hero{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:18px;border:1px solid #e6e8eb;border-radius:18px;background:linear-gradient(135deg,#fff,#f7f9fc)}.nzadmin-hero h2{margin:0 0 6px}.nzadmin-hero p{margin:0;color:#6b7280}.nzadmin-tools{display:flex;gap:7px;flex-wrap:wrap}.nzadmin-kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin:12px 0}.nzadmin-kpis div{background:#fff;border:1px solid #eceef1;border-radius:14px;padding:13px;text-align:center}.nzadmin-kpis b{display:block;font-size:20px}.nzadmin-kpis span{font-size:11px;color:#777}.nzadmin-tabs{display:flex;gap:6px;overflow:auto;margin:10px 0}.nzadmin-tabs a{white-space:nowrap;padding:9px 12px;border-radius:999px;border:1px solid #e1e4e8;text-decoration:none;font-weight:800}.nzadmin-tabs a.active{background:#111;color:#fff}.nzadmin-search{display:flex;gap:7px;margin:10px 0 14px}.nzadmin-search input{flex:1;border:1px solid #dfe2e6;border-radius:12px;padding:10px 12px;font:inherit}.nzadmin-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.nzadmin-health{display:flex;justify-content:space-between;padding:9px 0;border-bottom:1px solid #eee}.nzadmin-link{display:block;padding:11px 0;border-bottom:1px solid #eee;text-decoration:none;font-weight:800}.nzadmin-row{display:flex;gap:9px;align-items:center;padding:12px 0;border-top:1px solid #eceef1}.nzadmin-grow{flex:1;min-width:180px}.nzadmin-row small,.nzadmin-row a{display:block;margin-top:4px;color:#747b84;font-size:11px}.nzadmin-row em{font-style:normal;background:#fff1c2;color:#8a5a00;padding:2px 6px;border-radius:999px;font-size:10px}.nzadmin-row form{display:flex;gap:6px}.nzadmin-row input,.nzadmin-row select{border:1px solid #dfe2e6;border-radius:10px;padding:9px;font:inherit;max-width:190px}.nzadmin-inline{align-items:center}.nzasec-audit{padding:9px 0;border-top:1px solid #eee}.nzasec-audit b,.nzasec-audit span,.nzasec-audit small{display:block}.nzasec-audit span,.nzasec-audit small{color:#747b84;margin-top:3px;font-size:11px}@media(max-width:900px){.nzadmin-kpis{grid-template-columns:repeat(3,1fr)}.nzadmin-row{align-items:stretch;flex-direction:column}.nzadmin-row form{width:100%}.nzadmin-row input,.nzadmin-row select{flex:1;max-width:none}}@media(max-width:640px){.nzadmin-hero{align-items:flex-start;flex-direction:column}.nzadmin-grid{grid-template-columns:1fr}.nzadmin-kpis{grid-template-columns:repeat(2,1fr)}.nzadmin-search{flex-direction:column}.nzadmin-row form{flex-direction:column}}</style>';return str_replace('</head>',$css.'</head>',$html);
}

if((($_SERVER['REQUEST_METHOD']??'GET')==='POST')){
    $nzasecAction=(string)($_POST['action']??'');
    if(in_array($nzasecAction,['admin_block_user','admin_unblock_user','admin_send_notice','admin_set_post_status','admin_toggle_featured','admin_resolve_report','admin_reopen_report'],true))nzasec_handle_post($nzasecAction);
}
